ST.html:p:
(* First-scan initialization *)
IF FirstScan THEN
    TV_4750_03_Out := 6554;
    SV_104_01 := FALSE;
    FirstScan := FALSE;
    RETURN;
END_IF;

(* Scale analog inputs from 4-20 mA to engineering units *)
PI_4712_01_Scaled := ((INT_TO_REAL(PI_4712_01_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0 + 0.0;
PICSA_4712_02_Scaled := ((INT_TO_REAL(PICSA_4712_02_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0 + 0.0;
PWT_1202_Scaled := ((INT_TO_REAL(PWT_1202_Raw) - 6554.0) / (32767.0 - 6554.0)) * 250.0 + 0.0;
TICSA_4750_03_Scaled := ((INT_TO_REAL(TICSA_4750_03_Raw) - 6554.0) / (32767.0 - 6554.0)) * 300.0 + 0.0;

(* PI-4712.01 Four-level alarm logic with deadband *)
IF PI_4712_01_Scaled >= PI_4712_01_HH_SP THEN
    PI_4712_01_HH_LATCH.S1 := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH_LATCH.S1 := FALSE;
END_IF;

IF PI_4712_01_Scaled >= PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_LL_SP THEN
    PI_4712_01_LL_LATCH.S1 := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL_LATCH.S1 := FALSE;
END_IF;

(* PICSA-4712.02 Four-level alarm logic with deadband *)
IF PICSA_4712_02_Scaled >= PICSA_4712_02_HH_SP THEN
    PICSA_4712_02_HH_LATCH.S1 := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_HH_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_HH_LATCH.S1 := FALSE;
END_IF;

IF PICSA_4712_02_Scaled >= PICSA_4712_02_H_SP THEN
    PICSA_4712_02_H := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_H_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_H := FALSE;
END_IF;

IF PICSA_4712_02_Scaled <= PICSA_4712_02_L_SP THEN
    PICSA_4712_02_L := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_L_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_L := FALSE;
END_IF;

IF PICSA_4712_02_Scaled <= PICSA_4712_02_LL_SP THEN
    PICSA_4712_02_LL_LATCH.S1 := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_LL_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_LL_LATCH.S1 := FALSE;
END_IF;

(* PWT-1202 Four-level alarm logic with deadband *)
IF PWT_1202_Scaled >= PWT_1202_HH_SP THEN
    PWT_1202_HH_LATCH.S1 := TRUE;
ELSIF PWT_1202_Scaled <= (PWT_1202_HH_SP - PWT_1202_Deadband) THEN
    PWT_1202_HH_LATCH.S1 := FALSE;
END_IF;

IF PWT_1202_Scaled >= PWT_1202_H_SP THEN
    PWT_1202_H := TRUE;
ELSIF PWT_1202_Scaled <= (PWT_1202_H_SP - PWT_1202_Deadband) THEN
    PWT_1202_H := FALSE;
END_IF;

IF PWT_1202_Scaled <= PWT_1202_L_SP THEN
    PWT_1202_L := TRUE;
ELSIF PWT_1202_Scaled >= (PWT_1202_L_SP + PWT_1202_Deadband) THEN
    PWT_1202_L := FALSE;
END_IF;

IF PWT_1202_Scaled <= PWT_1202_LL_SP THEN
    PWT_1202_LL_LATCH.S1 := TRUE;
ELSIF PWT_1202_Scaled >= (PWT_1202_LL_SP + PWT_1202_Deadband) THEN
    PWT_1202_LL_LATCH.S1 := FALSE;
END_IF;

(* TICSA-4750.03 Four-level alarm logic with deadband *)
IF TICSA_4750_03_Scaled >= TICSA_4750_03_HH_SP THEN
    TICSA_4750_03_HH_LATCH.S1 := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_HH_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_HH_LATCH.S1 := FALSE;
END_IF;

IF TICSA_4750_03_Scaled >= TICSA_4750_03_H_SP THEN
    TICSA_4750_03_H := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_H_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_H := FALSE;
END_IF;

IF TICSA_4750_03_Scaled <= TICSA_4750_03_L_SP THEN
    TICSA_4750_03_L := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_L_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_L := FALSE;
END_IF;

IF TICSA_4750_03_Scaled <= TICSA_4750_03_LL_SP THEN
    TICSA_4750_03_LL_LATCH.S1 := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_LL_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_LL_LATCH.S1 := FALSE;
END_IF;

(* Execute alarm latches *)
PI_4712_01_HH_LATCH();
PI_4712_01_LL_LATCH();
PICSA_4712_02_HH_LATCH();
PICSA_4712_02_LL_LATCH();
PWT_1202_HH_LATCH();
PWT_1202_LL_LATCH();
TICSA_4750_03_HH_LATCH();
TICSA_4750_03_LL_LATCH();

(* Temperature control loop - TICSA-4750.03 *)
TICSA_4750_03_Error := TICSA_4750_03_SP - TICSA_4750_03_Scaled;
TICSA_4750_03_Integral := TICSA_4750_03_Integral + (TICSA_4750_03_Ki * TICSA_4750_03_Error);

IF TICSA_4750_03_Integral > 100.0 THEN
    TICSA_4750_03_Integral := 100.0;
ELSIF TICSA_4750_03_Integral < 0.0 THEN
    TICSA_4750_03_Integral := 0.0;
END_IF;

TICSA_4750_03_Output := (TICSA_4750_03_Kp * TICSA_4750_03_Error) + TICSA_4750_03_Integral;

IF TICSA_4750_03_Output > 100.0 THEN
    TICSA_4750_03_Output := 100.0;
ELSIF TICSA_4750_03_Output < 0.0 THEN
    TICSA_4750_03_Output := 0.0;
END_IF;

(* Pressure control loop - PICSA-4712.02 *)
PICSA_4712_02_Error := PICSA_4712_02_SP - PICSA_4712_02_Scaled;
PICSA_4712_02_Integral := PICSA_4712_02_Integral + (PICSA_4712_02_Ki * PICSA_4712_02_Error);

IF PICSA_4712_02_Integral > 100.0 THEN
    PICSA_4712_02_Integral := 100.0;
ELSIF PICSA_4712_02_Integral < 0.0 THEN
    PICSA_4712_02_Integral := 0.0;
END_IF;

PICSA_4712_02_Output := (PICSA_4712_02_Kp * PICSA_4712_02_Error) + PICSA_4712_02_Integral;

IF PICSA_4712_02_Output > 100.0 THEN
    PICSA_4712_02_Output := 100.0;
ELSIF PICSA_4712_02_Output < 0.0 THEN
    PICSA_4712_02_Output := 0.0;
END_IF;

(* Safety interlocks *)
IF TICSA_4750_03_HH_LATCH.Q1 OR PICSA_4712_02_HH_LATCH.Q1 THEN
    TV_4750_03_Out := 6554;
    SV_104_01 := FALSE;
ELSE
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TICSA_4750_03_Output / 100.0) * (32767.0 - 6554.0));
    SV_104_01 := HS_4750_01 AND (PICSA_4712_02_Output > 10.0);
END_IF;

(* Aggregate all alarm states *)
System_Alarm := 
    PI_4712_01_HH_LATCH.Q1 OR PI_4712_01_LL_LATCH.Q1 OR
    PI_4712_01_H OR PI_4712_01_L OR
    PICSA_4712_02_HH_LATCH.Q1 OR PICSA_4712_02_LL_LATCH.Q1 OR
    PICSA_4712_02_H OR PICSA_4712_02_L OR
    PWT_1202_HH_LATCH.Q1 OR PWT_1202_LL_LATCH.Q1 OR
    PWT_1202_H OR PWT_1202_L OR
    TICSA_4750_03_HH_LATCH.Q1 OR TICSA_4750_03_LL_LATCH.Q1 OR
    TICSA_4750_03_H OR TICSA_4750_03_L;
